{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.RLabs-Inc/gemini-mcp",
  "description": "Gemini 3 MCP server with 30+ tools: images, video, research, TTS, code exec & CLI",
  "repository": {
    "url": "https://github.com/RLabs-Inc/gemini-mcp",
    "source": "github"
  },
  "version": "0.7.2",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "@rlabs-inc/gemini-mcp",
      "version": "0.7.2",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "name": "GEMINI_API_KEY",
          "description": "Your Google Gemini API key (get one at https://aistudio.google.com/apikey)",
          "isRequired": true,
          "format": "string",
          "isSecret": true
        },
        {
          "name": "GEMINI_OUTPUT_DIR",
          "description": "Directory for generated files (images, videos, audio)",
          "isRequired": false,
          "format": "string",
          "isSecret": false
        }
      ]
    }
  ]
}
